const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Lac Rouge, Quebec, Canada.
  const aoi = ee.Geometry.Point([-71.4, 47.6]);
  const date2024 = ee.Date('2024-06-21');
  const date2025 = ee.Date('2025-06-15');

  // Define date ranges to search for images.
  const dateRange2024 = ee.DateRange(date2024.advance(-5, 'day'), date2024.advance(5, 'day'));
  const dateRange2025 = ee.DateRange(date2025.advance(-5, 'day'), date2025.advance(5, 'day'));

  // 2. Data Acquisition & Check
  // Use Sentinel-2 Level-2A data.
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Attempt to find images for the specified future dates.
  const col2024 = s2Collection.filterBounds(aoi).filterDate(dateRange2024);
  const col2025 = s2Collection.filterBounds(aoi).filterDate(dateRange2025);

  const count2024 = col2024.size().getInfo();
  const count2025 = col2025.size().getInfo();

  console.log(`Images found for June 2024: ${count2024}`);
  console.log(`Images found for June 2025: ${count2025}`);

  // 3. Validation & Final Answer
  // The query is for future dates, for which no satellite data exists.
  // This will result in an empty collection.
  if (count2024 === 0 || count2025 === 0) {
    console.log("Error: Requested dates are in the future. No satellite imagery is available.");
    console.log("C1");
    return;
  }

  // The following code would run if data existed, but it is unreachable.
  console.log("Error: This block should not be reached for future dates.");
  console.log("D");
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
